  Lemma pm_index_m1 : forall (w : pmw MI ST) c0 K (fx : FPState) A M model c R (key keyp ret : Z),
    PMS w c0 K -> frm_zero (@fp_csr fx) -> fconsts fx ->
    PMX w A M model c -> c_tr c = [] -> pm_bud (w_n w) c -> PmLoopU1.macct c ->
    2 * (Zlen (t3c (c_m1 c)) + 1) <= w_n w + 2 ->
    cregs w R ret ->
    getr R 10%bv = Z_to_bv 64 (w_p w + O_M1) -> getr R 11%bv = Z_to_bv 64 keyp ->
    cell4 SEGS M keyp key -> keyp mod 4 = 0 ->
    w_sp w <= keyp -> keyp + 4 <= w_sp0 w - 104 ->
    (forall (fx' : FPState) A' R' M' model' (p v : Z) (m1' : Z * Z * list (Z * (Z * Z))),
        frm_zero (@fp_csr fx') -> fconsts fx' -> PMX w A' M' model' (set_m1 c m1') -> pm_bud (w_n w) (set_m1 c m1') -> PmLoopU1.macct (set_m1 c m1') ->
        Zlen (t3c (c_m1 c)) <= Zlen (t3c m1') <= Zlen (t3c (c_m1 c)) + 1 ->
        kept R R' -> getr R' 10%bv = Z_to_bv 64 (p + 20) -> In (p, (key, v)) (t3c m1') -> 0 <= v < 2 ^ 32 ->
        CRep.agree_on (fun a => w_sp w <= a < w_sp0 w) M M' ->
        srealizes SEGS (cfg fx' R' ret M' model') K) ->
    srealizes SEGS (cfg fx R (ku_idx_u32 ccU1) M model) K.
